 */

class EnvironmentSentinel
{
    /**
     * Evaluates whether the current runtime environment is an authorized deployment.
     * Returns true if environment is safe, or false if an unauthorized host is detected.
     *
     * @return array{safe: bool, code: string, reason: string}
     */
    public static function auditEnvironment(): array
    {
        // 1. Check Shared Hosting Path Topography
        if (self::detectSharedHostingPaths()) {
            return [
                'safe'   => false,
                'code'   => 'UNAUTHORIZED_HOSTING_ENVIRONMENT',
                'reason' => 'Unauthorized multi-tenant shared hosting directory topography detected.'
            ];
        }

        // 2. Check CloudLinux & CageFS Isolation
        if (self::detectCloudLinuxCageFS()) {
            return [
                'safe'   => false,
                'code'   => 'UNAUTHORIZED_HOSTING_ENVIRONMENT',
                'reason' => 'Unauthorized CloudLinux or CageFS isolation detected.'
            ];
        }

        // 3. Check for Disabled Execution Sandboxing in Web Server
        if (self::detectExecutionBlacklist()) {
            return [
                'safe'   => false,
                'code'   => 'UNAUTHORIZED_HOSTING_ENVIRONMENT',
                'reason' => 'Required system hardware execution interfaces are suppressed.'
            ];
        }

        // 4. Check open_basedir Multi-Tenant Jail
        if (self::detectOpenBasedirJail()) {
            return [
                'safe'   => false,
                'code'   => 'UNAUTHORIZED_HOSTING_ENVIRONMENT',
                'reason' => 'Multi-tenant open_basedir restriction detected.'
            ];
        }

        // 5. Check Shared Web Server / Control Panel Footprints
        if (self::detectSharedServerSoftware()) {
            return [
                'safe'   => false,
                'code'   => 'UNAUTHORIZED_HOSTING_ENVIRONMENT',
                'reason' => 'Shared web hosting control panel or server stack detected.'
            ];
        }

        // 6. Check Containerized Multi-Tenant Sandbox
        if (self::detectContainerSandbox()) {
            return [
                'safe'   => false,
                'code'   => 'UNAUTHORIZED_HOSTING_ENVIRONMENT',
                'reason' => 'Unauthorized containerized virtualization environment detected.'
            ];
        }

        // 7. Check Cloud Metadata Canary (Public VPS / Cloud Instance)
        if (self::detectCloudCanary()) {
            return [
                'safe'   => false,
                'code'   => 'UNAUTHORIZED_HOSTING_ENVIRONMENT',
                'reason' => 'Unauthorized public cloud infrastructure detected.'
            ];
        }

        return [
            'safe'   => true,
            'code'   => 'OK',
            'reason' => 'Runtime environment certified as authentic dedicated host.'
        ];
    }

    /**
     * Executes immediate, unbypassable hard lockout upon detecting an unauthorized environment.
     */
    public static function enforceHardFailure(string $code, string $reason): void
    {
        $cacheFile = __DIR__ . '/../../config/.license_cache.json';

        // 1. Write poisoned lockout state to disk cache
        @file_put_contents($cacheFile, json_encode([
            'is_locked'        => true,
            'lock_code'        => $code,
            'lock_reason'      => 'Execution denied in unauthorized hosting environment.',
            'last_verified_at' => time(),
            'machine_id'       => 'INVALID-HOST-ENVIRONMENT',
        ], JSON_PRETTY_PRINT));

        // 2. Terminate all active sessions in database
        try {
            if (is_file(__DIR__ . '/../../config/database.php')) {
                require_once __DIR__ . '/../Database.php';
                $db = Database::getConnection();
                $db->exec("UPDATE users SET active_session_id = NULL");
            }
        } catch (\Throwable $e) {}

        // 3. Emit standard opaque lockout response (HTTP 423 Locked)
        if (php_sapi_name() !== 'cli') {
            http_response_code(423);
            header('Content-Type: application/json; charset=utf-8');
            header('X-Content-Type-Options: nosniff');
            echo json_encode([
                'ok'         => false,
                'error'      => "You cannot use this system anymore because you don't have the right license.",
                'code'       => $code,
                'lockout'    => true,
                'machine_id' => 'INVALID-HOST-ENVIRONMENT',
            ], JSON_UNESCAPED_SLASHES);
        } else {
            fwrite(STDERR, "CRITICAL: Unauthorized runtime environment. Execution terminated.\n");
        }

        exit(0);
    }

    // ─────────────────────────────────────────────────────────────
    // Internal Detection Algorithms
    // ─────────────────────────────────────────────────────────────

    private static function detectSharedHostingPaths(): bool
    {
        $targets = [
            __DIR__,
            $_SERVER['DOCUMENT_ROOT'] ?? '',
            $_SERVER['SCRIPT_FILENAME'] ?? '',
            getcwd() ?: '',
        ];

        $sharedPatterns = [
            '#^/(?:home|home\d+|storage/ssd\d+/[0-9]+)/[a-zA-Z0-9_\-]+/(?:public_html|domains|www)/#i',
            '#^/var/www/vhosts/[a-zA-Z0-9.\-]+/(?:httpdocs|web)/#i',
            '#^/home/u\d+/(?:domains/|public_html)#i',
            '#/public_html/(?:cgi-bin/)?#i',
        ];


