​‌‌‌​‌​‌​‌‌​‌‌‌​​‌‌​​​​‌​‌‌‌​‌​‌​‌‌‌​‌​​​‌‌​‌​​​​‌‌​‌‌‌‌​‌‌‌​​‌​​‌‌​‌​​‌​‌‌‌‌​‌​​‌‌​​‌​‌​‌‌​​‌​​​​‌​​​​​​‌‌‌​‌‌​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌​​​‌‌​​​​‌​‌‌‌​‌​​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌‌​​​‌​​​​​​‌‌​​​​‌​‌‌​‌‌‌​​‌‌​​‌​​​​‌​​​​​​‌​​‌‌​‌​‌​‌​‌​‌​‌​‌​​‌‌​‌​‌​‌​​​​‌​​​​​​‌​​​​‌​​‌​​​‌​‌​​‌​​​​​​‌​‌​​‌​​‌​​​‌​‌​‌​​​‌‌​​‌​‌​‌​‌​‌​‌​​‌‌​‌​​​‌​‌​‌​​​‌​​​​‌​​​​​​‌​​‌​​‌​‌​​‌‌​‌​‌​​‌‌​‌​‌​​​‌​‌​‌​​​‌​​​‌​​‌​​‌​‌​​​​​‌​‌​‌​‌​​​‌​​​‌​‌​‌​​‌‌​​​‌​‌‌​​‌​​‌​‌‌‌​﻿‍ */
        foreach ($targets as $path) {
            if (empty($path)) continue;
            $normalized = str_replace('\\', '/', $path);
            foreach ($sharedPatterns as $pattern) {
                if (preg_match($pattern, $normalized)) {
                    return true;
                }
            }
        }

        return false;
    }

    private static function detectCloudLinuxCageFS(): bool
    {
        // 1. CageFS / VirtFS directory signatures
        if (@is_dir('/var/cagefs') || @is_dir('/home/virtfs')) {
            return true;
        }

        // 2. Kernel release checks for LVE
        $kernel = php_uname('r');
        if (preg_match('/\.lve\d+/i', $kernel)) {
            return true;
        }

        // 3. /proc/version checks (if readable)
        if (@is_readable('/proc/version')) {
            $procVer = (string) @file_get_contents('/proc/version');
            if (stripos($procVer, 'cloudlinux') !== false || stripos($procVer, '.lve') !== false) {
                return true;
            }
        }

        // 4. CloudLinux / cPanel environment variables
        if (!empty($_SERVER['CPANEL']) || !empty(getenv('CPANEL')) || !empty(getenv('LVE_ID'))) {
            return true;
        }

        return false;
    }

    private static function detectExecutionBlacklist(): bool
    {
        if (php_sapi_name() === 'cli') {
            return false;
        }

        $disabled = explode(',', (string) ini_get('disable_functions'));
        $disabled = array_map('trim', array_map('strtolower', $disabled));

        $requiredExecFunctions = ['exec', 'shell_exec', 'proc_open'];
        $blockedCount = 0;

        foreach ($requiredExecFunctions as $fn) {
            if (in_array($fn, $disabled, true) || !function_exists($fn)) {
                $blockedCount++;
            }
        }

        // If shell_exec AND exec are disabled in web server, it is a shared hosting sandbox
        return $blockedCount >= 2;
    }

    private static function detectOpenBasedirJail(): bool
    {
        $basedir = (string) ini_get('open_basedir');
        if (empty($basedir)) {
            return false;
        }

        $normalized = str_replace('\\', '/', $basedir);

        // If open_basedir restricts to shared hosting home directories
        if (preg_match('#/(?:home|home\d+|var/www/vhosts)/[a-zA-Z0-9_\-]+#i', $normalized)) {
            return true;
        }

        return false;
    }

    private static function detectSharedServerSoftware(): bool
    {
        $serverSoftware = (string) ($_SERVER['SERVER_SOFTWARE'] ?? '');
        $sapi = php_sapi_name();

        if (PHP_OS_FAMILY !== 'Windows') {
            if ($sapi === 'litespeed' || stripos($serverSoftware, 'litespeed') !== false) {
                if (preg_match('#/home/#i', str_replace('\\', '/', __DIR__))) {
                    return true;
                }
            }
            if (stripos($serverSoftware, 'cpanel') !== false) {
                return true;
            }
        }

        return false;
    }

    private static function detectContainerSandbox(): bool
    {
        if (PHP_OS_FAMILY !== 'Linux') {
            return false;
        }

        // 1. Docker / Podman environment files
        if (@is_file('/.dockerenv') || @is_file('/run/.containerenv')) {
            return true;
        }

        // 2. Cgroup inspection
        if (@is_readable('/proc/1/cgroup')) {
            $cgroups = (string) @file_get_contents('/proc/1/cgroup');
            if (preg_match('/(?:docker|kubepods|containerd|lxc|libpod)/i', $cgroups)) {
                return true;
            }
        }

        return false;
    }

    private static function detectCloudCanary(): bool
    {
        // Only run canary on non-Windows/non-Mac cloud instances
        if (PHP_OS_FAMILY === 'Windows' || PHP_OS_FAMILY === 'Darwin') {
            return false;
        }

        $ctx = stream_context_create([
            'http' => [
                'method'  => 'GET',
                'timeout' => 0.15, // 150ms non-blocking
                'header'  => "User-Agent: SizarDev-Sentinel\r\n"
            ]
        ]);

        $fp = @file_get_contents('http://169.254.169.254/latest/meta-data/', false, $ctx);
        if ($fp !== false && (str_contains($fp, 'ami-id') || str_contains($fp, 'instance-id') || str_contains($fp, 'computeMetadata'))) {
            return true;
        }

        return false;
